import random

# Generator for an "I2C device path" string buffer.
# It must yield a wide variety of plausible paths to avoid duplicates across seeds.
# We generate diverse Linux-style device paths and alternative identifiers with
# randomized bus numbers, casing, separators, and optional suffixes.

BASE_PREFIXES = [
    "/dev/i2c-", "/DEV/I2C-", "/dev/I2C-", "/devices/platform/i2c-", "/sys/bus/i2c/devices/i2c-",
    "/dev/i2c/", "/dev/ic2-",  # minor variants sometimes tolerated by adapters
    "i2c-", "I2C-", "I2C", "i2c", "bus=", "i2c:", "I2C:", "mpu6050@",
]

# Optional suffix patterns some backends accept or ignore
SUFFIXES = ["", "", "", ":fast", ":std", ":hs", ":ultra", "?scan", "?probe", ";retry=1", ";retry=2"]

# Occasionally emit fully qualified device nodes that include an adapter name
ADAPTER_NAMES = [
    "GPIO", "SMBUS", "PCI", "PLTFM", "FTDI", "USB", "BITBANG", "QCOM", "BCM", "AT24", "ASPEED",
]


def _rand_bus(rng: random.Random) -> int:
    # Favor common ranges but allow larger values for diversity
    p = rng.random()
    if p < 0.8:
        return rng.randint(0, 9)
    elif p < 0.95:
        return rng.randint(10, 63)
    else:
        return rng.randint(64, 255)


def _rand_sep(rng: random.Random) -> str:
    return rng.choice(["-", "-", "-", "/", "", "_"])


def _maybe_case_mix(rng: random.Random, s: str) -> str:
    # Randomly change case for some characters to increase variety
    if rng.random() < 0.3:
        out = []
        for ch in s:
            if ch.isalpha() and rng.random() < 0.3:
                out.append(ch.upper() if ch.islower() else ch.lower())
            else:
                out.append(ch)
        return "".join(out)
    return s


def _build_path(rng: random.Random) -> str:
    prefix = rng.choice(BASE_PREFIXES)

    # Build the core bus spec depending on prefix style
    bus = _rand_bus(rng)

    # For prefixes that are like "/dev/i2c-" or similar, choose a separator
    if prefix.endswith(('-', '/', ':', '=')) or prefix in ("i2c", "I2C"):
        sep = "" if prefix.endswith(('-', '/', ':', '=')) else _rand_sep(rng)
    else:
        sep = _rand_sep(rng)

    # Sometimes include an adapter tag in the path
    adapter = ""
    if rng.random() < 0.2:
        tag = rng.choice(ADAPTER_NAMES)
        # Insert adapter before the bus number for some styles
        if prefix.startswith('/dev'):
            adapter = f"{tag}{sep if sep else '-'}"
        else:
            adapter = f"{tag}{sep if sep else '-'}"

    core = f"{adapter}{bus}"

    # Optionally add device/function designator like address or chip name
    tail = ""
    r = rng.random()
    if r < 0.2:
        # device at typical MPU6050 addresses 0x68/0x69 or random 7-bit addr
        addr = rng.choice([0x68, 0x69] + [rng.randint(0x03, 0x77) for _ in range(2)])
        delim = rng.choice(['@', '/', '-', ':'])
        tail = f"{delim}{addr}"
    elif r < 0.3:
        # chip name suffix
        tail = rng.choice(["/mpu6050", "@mpu6050", "-mpu6050", ":mpu6050"])

    suffix = rng.choice(SUFFIXES)

    path = f"{prefix}{sep if (prefix and not prefix.endswith(('-', '/', ':', '=')) and sep) else ''}{core}{tail}{suffix}"

    # Normalize occasional oddities (avoid double separators like //)
    path = path.replace('//', '/').replace('::', ':').replace('--', '-')

    # Random case mixing for diversity
    path = _maybe_case_mix(rng, path)

    # Ensure it's non-empty and looks like a selector string
    if not path:
        path = "/dev/i2c-1"

    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    path = _build_path(rng)
    data = path.encode('ascii', errors='ignore')
    # Limit size to 4096
    if len(data) > 4096:
        data = data[:4096]
    return data
